SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DELETE FROM dbo.sales_order_items;
DELETE FROM dbo.sales_orders;
DELETE FROM dbo.service_tickets;
DELETE FROM dbo.stocktake_entries;
DELETE FROM dbo.inventory_movements;
DELETE FROM dbo.purchase_order_items;
DELETE FROM dbo.purchase_orders;
DELETE FROM dbo.accounting_entries;
DELETE FROM dbo.channel_conversations;
DELETE FROM dbo.vouchers;
DELETE FROM dbo.inventory_items;
DELETE FROM dbo.suppliers;
DELETE FROM dbo.customers;
DELETE FROM dbo.products;

DBCC CHECKIDENT ('dbo.sales_order_items', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.sales_orders', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.service_tickets', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.stocktake_entries', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.inventory_movements', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.purchase_order_items', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.purchase_orders', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.accounting_entries', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.channel_conversations', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.vouchers', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.inventory_items', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.suppliers', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.customers', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.products', RESEED, 0) WITH NO_INFOMSGS;

CREATE TABLE #import_rows (
    import_id INT NOT NULL PRIMARY KEY,
    sale_date DATE NULL,
    customer_name NVARCHAR(150) NOT NULL,
    address NVARCHAR(255) NULL,
    phone NVARCHAR(30) NULL,
    product_name NVARCHAR(150) NOT NULL,
    color NVARCHAR(80) NULL,
    vin NVARCHAR(120) NOT NULL,
    list_price DECIMAL(15, 2) NOT NULL DEFAULT 0,
    branch_label NVARCHAR(80) NULL,
    sale_price DECIMAL(15, 2) NOT NULL DEFAULT 0,
    pay1_ck DECIMAL(15, 2) NOT NULL DEFAULT 0,
    pay1_tm DECIMAL(15, 2) NOT NULL DEFAULT 0,
    pay1_date DATE NULL,
    pay2_ck DECIMAL(15, 2) NOT NULL DEFAULT 0,
    pay2_tm DECIMAL(15, 2) NOT NULL DEFAULT 0,
    pay2_date DATE NULL,
    pay3_ck DECIMAL(15, 2) NOT NULL DEFAULT 0,
    pay3_tm DECIMAL(15, 2) NOT NULL DEFAULT 0,
    pay3_date DATE NULL,
    gift NVARCHAR(255) NULL,
    dms_flag NVARCHAR(20) NULL,
    note NVARCHAR(MAX) NULL,
    branch_id BIGINT NULL,
    product_id BIGINT NULL,
    customer_id BIGINT NULL,
    inventory_id BIGINT NULL,
    order_id BIGINT NULL,
    paid_total DECIMAL(15, 2) NULL,
    payment_method NVARCHAR(30) NULL
);


UPDATE #import_rows
SET
    sale_price = CASE WHEN sale_price <= 0 THEN list_price ELSE sale_price END,
    paid_total = pay1_ck + pay1_tm + pay2_ck + pay2_tm + pay3_ck + pay3_tm,
    payment_method = CASE
        WHEN ((CASE WHEN pay1_ck > 0 THEN 1 ELSE 0 END) + (CASE WHEN pay2_ck > 0 THEN 1 ELSE 0 END) + (CASE WHEN pay3_ck > 0 THEN 1 ELSE 0 END) +
              (CASE WHEN pay1_tm > 0 THEN 1 ELSE 0 END) + (CASE WHEN pay2_tm > 0 THEN 1 ELSE 0 END) + (CASE WHEN pay3_tm > 0 THEN 1 ELSE 0 END)) > 1 THEN N'INSTALLMENT'
        WHEN pay1_ck + pay2_ck + pay3_ck > 0 THEN N'BANK_TRANSFER'
        WHEN pay1_tm + pay2_tm + pay3_tm > 0 THEN N'CASH'
        ELSE N'CASH'
    END;

UPDATE #import_rows SET branch_id = CASE
    WHEN branch_label LIKE N'%LÊ LỢI%' OR branch_label LIKE N'%LE LOI%' THEN (SELECT TOP 1 id FROM dbo.branches WHERE phone = N'0815.018.555' OR name LIKE N'%Le Loi%' OR name LIKE N'%Lê Lợi%')
    WHEN branch_label LIKE N'%NAM ĐÀN%' OR branch_label LIKE N'%NAM DAN%' THEN (SELECT TOP 1 id FROM dbo.branches WHERE phone = N'0832.028.555' OR name LIKE N'%Nam Dan%' OR name LIKE N'%Nam Đàn%')
    WHEN branch_label LIKE N'%NGUYỄN DU%' OR branch_label LIKE N'%NGUYEN DU%' THEN (SELECT TOP 1 id FROM dbo.branches WHERE phone = N'0815.016.555' OR name LIKE N'%Nguyen Du%' OR name LIKE N'%Nguyễn Du%')
    ELSE NULL
END;

SELECT DISTINCT CONCAT(N'Kho ', branch_label), N'Chua cap nhat dia chi', NULL, 1
FROM #import_rows source
WHERE source.branch_id IS NULL
  AND source.branch_label IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM dbo.branches existing WHERE existing.name = CONCAT(N'Kho ', source.branch_label));

UPDATE source
SET branch_id = existing.id
FROM #import_rows source
JOIN dbo.branches existing ON existing.name = CONCAT(N'Kho ', source.branch_label)
WHERE source.branch_id IS NULL;

IF EXISTS (SELECT 1 FROM #import_rows WHERE branch_id IS NULL)
BEGIN
    THROW 51000, 'Khong xac dinh duoc chi nhanh cho mot so dong import.', 1;
END;

SELECT product_name, N'VinFast', product_name, color,
       CASE WHEN product_name LIKE N'%XE ĐẠP%' OR product_name LIKE N'%XE DAP%' THEN N'E_BICYCLE' ELSE N'E_MOTORBIKE' END,
       NULL, 36, MAX(list_price), CONCAT(N'CP-', UPPER(REPLACE(REPLACE(product_name, N' ', N'-'), N'Đ', N'D'))), N'Nhap tu FILE NHAP.xlsx'
FROM #import_rows
GROUP BY product_name, color;

UPDATE source
SET product_id = product.id
FROM #import_rows source
JOIN dbo.products product ON product.name = source.product_name AND ISNULL(product.color, N'') = ISNULL(source.color, N'');

CREATE TABLE #customer_map (import_id INT NOT NULL PRIMARY KEY, customer_id BIGINT NOT NULL);
MERGE dbo.customers AS target
USING #import_rows AS source
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (full_name, phone, email, address, birthday, loyalty_points, tier, source)
    VALUES (source.customer_name, ISNULL(NULLIF(source.phone, N''), N'Chua co SDT'), NULL, source.address, NULL, 0, N'NEW', N'FILE NHAP')
OUTPUT source.import_id, inserted.id INTO #customer_map;

UPDATE source SET customer_id = map.customer_id
FROM #import_rows source
JOIN #customer_map map ON map.import_id = source.import_id;

CREATE TABLE #inventory_map (import_id INT NOT NULL PRIMARY KEY, inventory_id BIGINT NOT NULL);
MERGE dbo.inventory_items AS target
USING #import_rows AS source
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (branch_id, product_id, serial_number, imei, vehicle_code, status, cost_price)
    VALUES (source.branch_id, source.product_id, source.vin, CONCAT(N'NOIMEI-', source.import_id), CONCAT(N'VIN-', source.import_id), N'SOLD', NULL)
OUTPUT source.import_id, inserted.id INTO #inventory_map;

UPDATE source SET inventory_id = map.inventory_id
FROM #import_rows source
JOIN #inventory_map map ON map.import_id = source.import_id;

CREATE TABLE #order_map (import_id INT NOT NULL PRIMARY KEY, order_id BIGINT NOT NULL);
MERGE dbo.sales_orders AS target
USING #import_rows AS source
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (order_code, branch_id, customer_id, subtotal, discount, tax, deposit_amount, total, voucher_code, payment_method, status, created_at)
    VALUES (CONCAT(N'NHAP-', RIGHT(CONCAT(N'000000', source.import_id), 6)), source.branch_id, source.customer_id, source.list_price,
            CASE WHEN source.list_price > source.sale_price THEN source.list_price - source.sale_price ELSE 0 END,
            0, CASE WHEN source.pay1_ck + source.pay1_tm > 0 THEN source.pay1_ck + source.pay1_tm ELSE source.paid_total END,
            source.sale_price, NULL, source.payment_method, N'PAID', COALESCE(CAST(source.sale_date AS DATETIME2), SYSDATETIME()))
OUTPUT source.import_id, inserted.id INTO #order_map;

UPDATE source SET order_id = map.order_id
FROM #import_rows source
JOIN #order_map map ON map.import_id = source.import_id;

SELECT order_id, product_id, inventory_id, 1, sale_price, sale_price FROM #import_rows;

SELECT N'SALE', inventory_id, product_id, branch_id, NULL, 1, vin, 0, CONCAT(N'Ban xe import tu FILE NHAP.xlsx. Qua tang: ', ISNULL(gift, N''), N'. Note: ', ISNULL(note, N'')) FROM #import_rows;

SELECT CONCAT(N'NK-', RIGHT(CONCAT(N'000000', import_id), 6)), COALESCE(sale_date, CAST(GETDATE() AS DATE)), N'INCOME', N'Doanh thu ban xe import', branch_id, customer_name,
       CONCAT(N'VIN ', vin, N' - ', product_name, N' ', ISNULL(color, N'')), CASE WHEN paid_total > 0 THEN paid_total ELSE sale_price END, payment_method, N'POSTED'
FROM #import_rows;

VALUES (N'Codex', N'IMPORT', N'FILE_NHAP', NULL, CONCAT(N'Import ', (SELECT COUNT(*) FROM #import_rows), N' dong tu FILE NHAP.xlsx va xoa du lieu kinh doanh cu'));

COMMIT TRANSACTION;

SELECT (SELECT COUNT(*) FROM dbo.customers) AS customers,
       (SELECT COUNT(*) FROM dbo.products) AS products,
       (SELECT COUNT(*) FROM dbo.inventory_items) AS inventory_items,
       (SELECT COUNT(*) FROM dbo.sales_orders) AS sales_orders,
       (SELECT SUM(total) FROM dbo.sales_orders) AS revenue_total;


